engineering['lens-bench']=seq(64).map(i=>{const focal=[10,20,-10,30],spacings=[10,20,30,40],lensProof=[i%4,(i/4|0)%4,(i/16|0)%4];if(!baseEng['lens-bench'].rules.model(focal[lensProof[0]],focal[lensProof[1]],spacings[lensProof[2]]).finite)return null;return{objective:'Tìm hai lens và khoảng cách cho đúng vị trí, chiều và độ phóng đại ảnh; phân biệt ảnh thật/ảo.',singleStage:true,content:{focal,spacings,lensProof},resources:{focal,spacings},hints:['Lens âm làm phân kỳ, không chỉ là lens yếu.','Phải khớp cảzvà độ phóng đại m.','Đường tia cho biết vì sao một cấu hình cho ảnh vô cực.']};}).filter(Boolean).slice(0,32);
for(const config of engineering['lens-bench']){for(let code=0;code<64;code++){const state=baseEng['lens-bench'].create();state.f1=code%4;state.f2=(code/4|0)%4;state.spacing=(code/16|0)%4;state.content=clone(config.content);const checked=baseEng['lens-bench'].step(state,cmd('test'));if(!checked.cleared&&checked.status==='playing'){config.state={f1:state.f1,f2:state.f2,spacing:state.spacing};break;}}}
engineering['radar-triangulation']=seq(32).map(i=>{const stations=[{x:70+(i%4)*30,y:60},{x:610,y:100+(i/4|0)*18},{x:90+(i%3)*20,y:420}],origin={x:230+(i%8)*20,y:160+(i/8|0)*25},velocity={x:2+(i%3),y:i&1?-2:2};return{objective:'Ước lượng mục tiêu chuyển động từ ba trạm có nhiễu, đồng bộ thời gian và kiểm sai số<15.',singleStage:true,content:{stations},state:{origin,velocity,budget:i>=24?5:8},resources:{stations,velocity},hints:['Ba mẫu từ một trạm không thay được ba trạm không thẳng hàng.','Mỗi mẫu đo ở thời gian riêng; phải trừ vận tốc×thời gian.','LS dùng chính các phép đo có nhiễu, không đọc tọa độ thật.']};});
write('engineering','learning',engineering,puzzleCh,puzzleMech);
const science={},baseSci=require('../all-game-exp-science.js').games;
science['reaction-lab']=seq(32).map(i=>{const stages=[{target:1+i%3,temperature:60+((i/3|0)%3)*20},{target:1+(i/9|0)%3,temperature:80},...(i>=16?[{target:1+(i/9|0)%2,temperature:100}]:[])],total=stages.reduce((n,v)=>n+v.target,0);return{objective:'Sản xuất và giao từng mẻ theo chuỗi hư cấu A+2B→X, đúng trình tự, nhiệt độ và không dư.',singleStage:true,content:{stages,reactionTemperature:stages[0].temperature},state:{target:stages[0].target,stockA:total,stockB:total*2},resources:{stages,reagentsA:total,reagentsB:total*2},hints:['Đây là mô hình hư cấu, không dùng làm thí nghiệm hóa chất.','Mỗi mẻ: thêmA,đưa40°,hòa tan,thêm2B/A,rồi đặt nhiệt phản ứng.','Sau giao mẻ, hòa tan lại nguyên liệu của mẻ kế tiếp; khối lượng gồm cả sản phẩm đã giao.']};});
science['genetics-garden']=seq(32).map(i=>{const probabilities=[0,.25,.5,1],breedingGoals=seq(3).map(k=>({probability:probabilities[(i>>(k*2))%4]}));return{objective:'Suy luậnAA/Aatừ mẫu lai kiểm chứng rồi hoàn thành ba phép lai theo tỷ lệ lý thuyết; phân biệt mẫu hữu hạn với xác suất.',singleStage:true,content:{breedingGoals},state:{hidden:i%2,budget:i<16?4:2},resources:{breedingGoals,testCross:'aa',sampleSize:32},hints:['Có con trắng trong lai aa chứng tỏ mẫu bố/mẹ mang a.','Aa×Aa cho25%,Aa×aa cho50%,aa×aa cho100%; cóAAcho0%.','Kết quả16con có dao động; chấm theoPunnett, không ép số con giả.']};});
const geoSeen=new Set(),geoSequences=[];function permute(a){if(!a.length)return[[]];return a.flatMap((v,i)=>permute(a.filter((_,k)=>k!==i)).map(p=>[v,...p]));}for(const proof of permute(['A','B','C','fault','intrusion','erode'])){const target=baseSci['geology-strata'].rules.model(proof),key=target.join();if(geoSeen.has(key))continue;geoSeen.add(key);geoSequences.push({proof,target});if(geoSequences.length===32)break;}
science['geology-strata']=geoSequences.map(({proof,target})=>({objective:'Tái dựng sáu sự kiện để khớp mặt cắt; dùng cắt xuyên, đứt gãy và xói mòn suy thứ tự.',singleStage:true,content:{geologyProof:proof},state:{target},resources:{events:proof},hints:['Lớp trẻ phủ lên lớp cũ, nhưng xói mòn có thể xóa dấu.','Xâm nhập chỉ cắt các lớp tồn tại khi nó diễn ra.','Hai thứ tự cùng tên sự kiện có thể cho mặt cắt khác nhau.']}));
science['thermal-transit']=seq(32).map(i=>{const energy=[380+(i%4)*30,10+(i/4|0)%4*10,10+(i%3)*10,0,0],materials=[1,1,1,0];return{objective:'Dẫn năng lượng qua cổng chuyển pha, giữ bến lạnh và bảo toàn tổng năng lượng trong45s.',singleStage:true,content:{receiverMax:i<16?30:25},state:{energy,initialEnergy:energy.reduce((a,b)=>a+b),materials},resources:{initialEnergy:energy,materialStock:i>=16?[2,2,2,0]:[0,0,0,2]},hints:['Liên kết cuối cần cách nhiệt để giữ bến lạnh.','Ba liên kết đầu cần dẫn tốt để cổngE3đạt90.','Tổng năng lượng không tự sinh; nhiệt độ ở vùng chuyển pha không tăng ngay.']};});
science['crystal-symmetry']=seq(32).map(i=>{const motif=[[0,0],[1,0],[1,2],[2,2],...seq(1+(i%4)).map(k=>[(i+k*2)%5,(i/4+k|0)%5])].filter((p,k,a)=>a.findIndex(q=>q.join()===p.join())===k),proof=[...(i&1?['mirror']:[]),...seq(1+(i%3)).map(()=> 'rotate'),...seq(i%5).map(()=> 'shiftx'),...seq((i/5|0)%5).map(()=> 'shifty')],target=proof.reduce(baseSci['crystal-symmetry'].rules.transform,clone(motif));return{objective:'Khớp motif nhiều điểm bằng tổ hợp quay, phản chiếu và dịch chu kỳ; thứ tự phép biến đổi có ý nghĩa.',singleStage:true,content:{crystalProof:proof,motif},state:{points:motif,target},resources:{motif},hints:['So quan hệ giữa các điểm để nhận ra chiều quay/gương.','Quay và dịch không giao hoán.','Dịch theo mod5; có nhiều chuỗi hợp lệ dưới20phép.']};});
write('science','learning',science,puzzleCh,puzzleMech);

const storyCh=['Lời nhắn từ Bình Minh','Những đường rẽ đầu tiên','Điều còn lại sau cơn mưa','Giữ lời với người đồng hành','Ngày mới trên quần đảo'],storyMech=['Quan sát rồi xác minh','Dùng tri thức để mở đường','Quyết định có nguồn lực và hậu quả','Kết hợp các hệ thống đã học','Kết cục theo những cam kết đã giữ'];
const storyArcs={"station-detective":{"speaker":"Linh · điều tra viên","texts":["Trạm Bình Minh mất lõi năng lượng. Nhân chứng An muốn lời khai được giữ kín trong lúc bạn kiểm tra chuỗi thời gian.","Một bản ghi sao chép khiến nhóm điều tra nghi ngờ lẫn nhau. Chia hồ sơ đối chiếu có thể giúp nhân chứng sửa sai, nhưng bạn phải chấp nhận thêm nguồn cần kiểm chứng.","Tên người dùng thẻ mở kho đã rõ. Bạn có công bố toàn bộ bối cảnh để trạm cùng khôi phục niềm tin, hay chuyển hồ sơ tối thiểu và tự bảo vệ nguồn tin?"]},"relic-room":{"speaker":"Kha · thợ phục dựng","texts":["Cánh cửa trong đền không mở bằng sức mạnh. Kha xin cùng đọc bản khắc và giữ kho phụ tùng, đổi lại bạn phải tin cách làm của người mới.","Cơ cấu cũ mang dấu tay nhiều đời thợ. Giữ một phần dụng cụ cho nhóm bảo tồn sẽ để họ hỗ trợ phòng kế tiếp.","Sau cánh cửa cuối là nhật ký của những người đã rời đảo. Bạn chọn để cộng đồng cùng phục dựng hay giữ một bản sao và hoàn tất tuyến riêng."]},"clockloop-story":{"speaker":"An · người gác tháp","texts":["Ngày mưa lặp lại, chỉ bạn nhớ cầu sẽ gãy. An đề nghị ghi chung các mốc giờ để cứu người thay vì chạy thẳng khỏi trạm.","Kỹ sư tin lời bạn sau khi thấy một sự kiện lặp đúng. Bạn có dành thêm một vòng để họ chuẩn bị phương án gia cố?","Đã có cửa sổ gọi thuyền. Quyết định trước chuyến cuối xác định ai giữ lịch vận hành khi vòng lặp chấm dứt."]},"treaty-dialogue":{"speaker":"Diệp · người hòa giải","texts":["Hai bờ sông cùng thiếu nước nhưng không tin số đo của nhau. Diệp muốn lập đoàn đo chung trước khi đàm phán điều khoản.","Một hành lang qua sông sẽ giúp cứu trợ, đồng thời khiến cả hai bên lo mất quyền kiểm soát. Bạn chọn xây lòng tin hay giữ khoản dự trữ tự chủ?","Bản hiệp ước đã gần đủ. Chọn chia nguồn lực cho cơ chế giám sát chung hoặc hoàn tất bằng các bảo đảm riêng sẽ định hình ngày hòa bình đầu tiên."]},"cartographer-expedition":{"speaker":"Hà · hoa tiêu","texts":["Bản đồ cũ bỏ trống bờ phía đông. Hà xin chia tiếp tế để một nhóm dân đảo cùng đánh dấu những mốc đường về.","Một địa danh trên bản đồ chỉ còn tên gọi trong ký ức người già. Hợp tác khảo sát mở thêm hỗ trợ hậu cần cho tuyến kế.","Trước khi về trại, bạn phải quyết định bản đồ mới thuộc sổ riêng hay trở thành tuyến đường chung của quần đảo."]},"party-jrpg":{"speaker":"Vy · y sĩ đội thám hiểm","texts":["Ba người bảo vệ đoàn dân rời trạm. Vy muốn giữ nguồn hồi phục cho cả những người đang ở phía sau đội hình.","Pháp sư phát hiện các hộ vệ dùng năng lượng từ rễ đảo. Chia sẻ nguồn phép với đồng minh sẽ giúp Vy duy trì cứu chữa.","Đợt phòng thủ cuối cần một người ở lại giữ đường rút. Lựa chọn của bạn định hình đội hình có thể cùng trở về hay mỗi người tự giữ lời hứa."]},"ability-gated-quest":{"speaker":"Mộc · người mở đường","texts":["Những lối đi trên đảo đóng sau cơn bão. Mộc biết cách học lướt và nhảy, nhưng cần bạn mang dấu đường cho nhóm theo sau.","Ấn cổ không chỉ mở cửa cho một người. Bạn có trao lại đường đã khám phá để nhóm thợ chuẩn bị điểm nghỉ?","Hộ vệ chặn lối vào lõi sáng. Trước trận cuối, bạn chọn dựa vào mạng lưới đồng hành hay tiếp tục tuyến khám phá tự chủ."]},"survivor-camp":{"speaker":"Nam · người giữ lửa","texts":["Đêm đầu trên đảo lạnh và kho vật tư ít. Nam muốn chia phần thức ăn để một nhóm khác có thể tìm củi cho trại chung.","Mái trại đã đứng vững nhưng mưa chưa dứt. Bạn chọn dành nguồn lực cho điểm trú chung hay giữ dự trữ ở trại riêng?","Khói lửa sẽ là tín hiệu cuối cùng gửi tàu cứu hộ. Quyết định trước đêm cuối ghi nhớ cách bạn chăm những người cùng mắc kẹt."]},"creature-tamer":{"speaker":"Chi · nhà quan sát","texts":["Sinh vật trên đảo sợ những người đến gần. Chi đề nghị chia khu trú và quan sát thay vì ép chúng mở lối.","Một loài mới chỉ đến khi môi trường đủ yên. Bạn chọn chăm sinh cảnh chung hay giữ nguồn dự trữ cho nhóm mình?","Đường về đã mở nhờ những người bạn mới. Bạn quyết định để lại mạng lưới chăm sóc hay ghi chép một tuyến thám hiểm độc lập."]},"wildlife-tracker":{"speaker":"Lâm · kiểm lâm đảo","texts":["Dấu chân đầu tiên dẫn về vùng làm tổ. Lâm muốn chia ghi chép để mọi người biết khoảng cách quan sát an toàn.","Một cơn đổi gió làm lộ vị trí người theo dấu. Hỗ trợ nhóm quan sát giữ tuyến khuất mùi sẽ thay đổi khả năng chịu sai sót của chuyến đi.","Bức ảnh cuối có thể chỉ là thành tích riêng hoặc trở thành hồ sơ bảo vệ sinh cảnh. Bạn chọn cách kể hành trình của mình."]}};
function branching(id,configs,effect){return configs.map((config,i)=>{config.flagEffects=[0,8,16].map(n=>({key:id+'-choice-'+n,value:'share',field:effect.field,delta:effect.delta}));if([0,8,16].includes(i)){config.choiceKey=id+'-choice-'+i;config.speaker=storyArcs[id]?.speaker||'Nhật ký Bình Minh';config.storyText=['Một nhóm người mắc kẹt nhờ bạn chia một phần nguồn lực. Quyết định được giữ trong hành trình.','Đồng minh cũ trở lại với đề nghị hợp tác, đổi dự trữ lấy sự tin tưởng.','Trước chặng cuối, bạn quyết định giữ mạng lưới hỗ trợ hay hoàn thành tuyến tự chủ.'][i/8];if(storyArcs[id])config.storyText=storyArcs[id].texts[i/8];config.choices=[{id:'share',label:'Chia sẻ và cùng tìm lời giải',consequence:'Bạn chọn hợp tác; hồ sơ và nguồn lực hỗ trợ thay đổi từ nhiệm vụ này.',state:effect.share||{},content:effect.contentShare||{}},{id:'reserve',label:'Giữ dự trữ, tự đi tuyến riêng',consequence:'Bạn giữ tuyến tự chủ; nguồn dự trữ khác và kết cục ghi nhớ quyết định.',state:effect.reserve||{},content:effect.contentReserve||{}}];}return config;});}
const narrative={},baseNarr=require('../all-game-exp-narrative.js').games;
narrative['station-detective']=branching('station-detective',seq(20).map(i=>{const decoy=i%5,order=seq(5).filter(k=>k!==decoy);for(let k=0;k<i%4;k++)order.push(order.shift());const culprit=i%3,names=['An','Bình','Chi'],clues=seq(5).map(k=>['Khu '+(k+1),k===decoy?['Đồng hồ lệch12phút; mốc này không thuộc chuỗi chứng cứ.','Bản ghi là bản phát lại hôm trước, không phải âm thanh trực tiếp.','Ảnh phản chiếu đảo thứ tự, không dùng làm mốc thật.','Phiếu có số hiệu trùng do sao chép; đối chiếu bản gốc.'][i/5|0]:'18:'+String(3+order.indexOf(k)*4).padStart(2,'0')+' · '+['Sổ cửa xác nhận ai rời chốt.','Dấu nước cho thấy đường dưới mái đã được dùng.','Khóa mở bằng thẻ của '+names[culprit]+'.','Nhân chứng trực tiếp thấy '+names[culprit]+' mang lõi.'][order.indexOf(k)]]);return{objective:'Khám năm nguồn, loại mốc không đáng tin, xếp bốn chứng cứ theo thời gian và chỉ ra người dùng thẻ mở kho.',content:{clues,timeline:order,culprit},state:{maxErrors:3},resources:{evidence:5,decoyType:i/5|0},hints:['Đọc dấu hiệu sai lệch của nguồn gây nhiễu.','Bốn nguồn thật ghi thời gian tăng dần.','Thẻ mở khóa và nhân chứng phải cùng chỉ một người.']};}),{field:'maxErrors',delta:1,share:{maxErrors:4},reserve:{maxErrors:3}});
narrative['relic-room']=branching('relic-room',seq(20).map(i=>{const rooms=seq(2+i%3).map((_,k)=>{const target=(k===0?i%4:(i/4|0)+k-1)%4,pickups=seq(4).filter(j=>j!==target).slice(0,(i+k)%2?3:2),parts=pickups.map((_,j)=>'part-'+k+'-'+j),items=seq(4).map(j=>j===target?['Cửa vòm','Máng nước','Giàn cầu','Bệ lõi'][(i+k)%4]:pickups.includes(j)?['Cán đồng','Móc dây','Bánh khóa'][pickups.indexOf(j)]:'Bản khắc chỉ cách ghép');return{name:'Phòng cơ cấu '+(k+1),items,parts,pickups,made:'tool-'+k,target};});return{objective:'Khám các bộ phận, ghép đúng dụng cụ rồi dùng vào vật chắn; hoàn thành toàn bộ tuyến phòng.',content:{rooms},state:{maxActions:45},resources:{rooms:rooms.length,partsPerRoom:rooms.map(r=>r.parts.length)},hints:['Bản khắc phân biệt bộ phận nhặt được và vật chắn.','Mỗi phòng cần tất cả bộ phận của nó trước khi kết hợp.','Chọn đúng vật chắn rồi dùng dụng cụ đã trang bị.']};}),{field:'maxActions',delta:2,share:{maxActions:48},reserve:{maxActions:45}});
