function crossGrid(index){const words=[];const occupied={};for(let k=0;k<3+index%3;k++){const candidates=[];for(const [word,clue]of dictionary)for(let vertical=0;vertical<2;vertical++)for(let pos=0;pos<20;pos++){const x=pos%5,y=pos/5|0;if(x+(!vertical?word.length:1)>5||y+(vertical?word.length:1)>4)continue;const slots=seq(word.length).map(j=>pos+j*(vertical?5:1));if(words.some(w=>w.slots.join()===slots.join()))continue;let matches=0,ok=true;slots.forEach((i,j)=>{if(occupied[i]&&occupied[i]!==word[j])ok=false;else if(occupied[i])matches++;});if(!ok||words.length&&(matches===0||matches===word.length))continue;if(!words.length&&(vertical||y!==1))continue;candidates.push({word,clue,slots});}if(!candidates.length)break;const c=candidates[(index*37+k*13)%candidates.length];c.slots.forEach((v,j)=>occupied[v]=c.word[j]);words.push(c);}return words;}
language['vietnamese-crossword']=seq(32).map(i=>{const entries=crossGrid(i),crossData=entries.map((e,k)=>[e.word,(i/8|0)===0?e.clue:(i/8|0)===1?'Dựa vào nghĩa và giao điểm: '+e.clue:(i/8|0)===2?'Loại đáp án sai số chữ; suy từ mô tả: '+e.clue:'Giải thích bằng khái niệm, đối chiếu các chữ chung: '+e.clue]);return{objective:'Giải lưới '+entries.length+'mục liên thông; dùng nghĩa, số ô và chữ giao để loại giả thuyết.',singleStage:true,content:{crossData,crossCells:entries.map(e=>e.slots)},resources:{entries:entries.length,inference:['nghĩa','độ dài','giao điểm']},hints:['Mỗi clue mô tả một khái niệm; không lấy chữ có dấu làm ô riêng.','Từ giao phải dùng cùng một chữ ở ô chung.','Bộ nội dung được tự biên soạn; có thể nhập có/không dấu.']};});
const tilePositions=[],tileSeen=new Set();for(let seed=1;tilePositions.length<32&&seed<200;seed++){const engine=baseLang['word-tiles'];let s=engine.create({seed,difficulty:'normal'});for(let turn=0;turn<2&&s.status==='playing';turn++){const moves=engine.rules.tileMoves(s,s.racks[0]);if(!moves.length)break;const m=moves[(seed+turn*7)%Math.min(12,moves.length)];s=engine.step(s,cell(m.pos));if(s.vertical!==m.vertical)s=engine.step(s,cmd('rotate'));s=engine.step(s,{type:'text',value:m.word});s=engine.step(s,cmd('submit'));const next=engine.rules.tileMoves(s,s.racks[0]),key=s.board.join('|')+'|'+s.racks[0].slice().sort().join();if(s.status==='playing'&&next.length&&!tileSeen.has(key)){tileSeen.add(key);tilePositions.push({state:clone(s),move:next[Math.min(next.length-1,seed%4)]});if(tilePositions.length===32)break;}}}
language['word-tiles']=tilePositions.map(({state,move},i)=>({objective:'Từ thế cờ hợp lệ, đặt một từ nối bàn đạt≥'+move.score+'điểm và đi qua các ô chỉ định; mọi từ giao phải thuộc bộ từ.',state,training:{minScore:move.score,required:move.put.slice(0,Math.min(2,move.put.length)).map(index=>({index,letter:move.board[index]}))},proof:move,resources:{rack:state.racks[0],requiredCells:move.put.slice(0,2)},hints:['Các thế bàn được tạo bằng những lượt đặt từ hợp lệ đầy đủ, gồm phản hồi bot.','Tìm chữ giao sẵn để tiết kiệm rack và tăng điểm.','Đặt từ đáp ứng ô nhiệm vụ; Quick Play vẫn giữ đủ sáu lượt đối kháng.']}));
