language['cipher-workbench']=seq(32).map(i=>{const phrase=phrases32[i].slice(0,28),mode=i/8|0,alphabet=seq(26).map(k=>String.fromCharCode(65+(mode===0?(k+3+i%5)%26:mode===1?25-k:mode===2?(5*k+8)%26:(7*k+3)%26))),cipher=Array.from(phrase).map(v=>v===' '?' ':alphabet[v.charCodeAt(0)-65]).join(''),cipherClue=['Caesar:chữmã=(chữrõ+'+(3+i%5)+')mod26.','Atbash:chữmã=25−chữrõ.','Affine:chữmã=(5×chữrõ+8)mod26.','Affine:chữmã=(7×chữrõ+3)mod26.'][mode];return{objective:'Giải mật thư bằng quy tắc công bố,mẫu lặp và ánh xạ một–một; kiểm chứng toàn câu.',singleStage:true,content:{phrase,cipherClue},state:{alphabet,cipher,selected:cipher.replace(/ /g,'')[0]},resources:{scheme:mode},hints:['A=0,B=1,…,Z=25. Quy tắc trong HUD biến chữ rõ thành chữ mã.','Mọi vị trí cùng chữ mã phải nhận cùng chữ rõ; không gán trùng hai chữ mã.','Đối chiếu toàn câu trước khi nộp.']};});
