creative['bonsai-topiary']=seq(20).map(i=>{const branches=clone(baseCreative['bonsai-topiary'].rules.initialBranches);branches[0].length=70+(i%4)*5;branches[1].angle=-150+(i%4)*10;branches[2].angle=-30-(i/4|0)*5;branches[4].length=42+(i%5)*3;let sample=baseCreative['bonsai-topiary'].create();sample.branches=clone(branches);sample=baseCreative['bonsai-topiary'].step(sample,cmd('branch-3'));sample=baseCreative['bonsai-topiary'].step(sample,cmd('prune'));for(let k=0;k<3;k++)sample=baseCreative['bonsai-topiary'].step(sample,cmd('season'));const m=baseCreative['bonsai-topiary'].rules.metrics(sample),bonsaiRubric={width:[Math.max(40,m.width-14),m.width+14],height:[m.height-14,m.height+14],balance:m.balance+12,vigor:10,alive:4};return{objective:'Chăm cây qua ba mùa,theo dải tán/cao/cân bằng của brief;giữ ít nhấtbốnnhánhsống và sức sống≥10.',state:{branches},content:{bonsaiRubric},resources:{bonsaiRubric,seasons:3},hints:['Cắt nhánh làm mất cả nhánh con,không mọc lại tức thì.','Ánh sáng thay sức sống và tốc độ dài của từng phía.','Có nhiều cây hợp rubric;nhánh ngang dài là một lựa chọn cắt,không bắt buộc tọa độ.']};});
creative['perspective-camera']=seq(20).map(i=>{const camera={x:-4+(i%5)*2,z:(i/5|0)},sceneObjects=[{x:0,z:12,w:1.5,h:3,color:'#e8b18e',subject:true},{x:camera.x<=0?-5:5,z:7,w:1.6,h:4,color:'#47775c'},{x:3,z:16+(i%3),w:3,h:5,color:'#658598'}],sample=baseCreative['perspective-camera'].create();sample.content={sceneObjects};sample.camera=camera;sample.focal=80;sample.exposure=1/120;const subject=baseCreative['perspective-camera'].rules.project(sample,sceneObjects[0]),photoBrief={screen:subject.x,size:subject.h};return{objective:'Chụp chủ thể ở vị trí/kích thước của đơn,giữ che khuất<15%và nhòe≤3px;dùng parallax thay vì chỉ zoom.',singleStage:true,content:{sceneObjects,photoBrief},proof:{camera,focal:80,exposure:1/120},resources:{photoBrief},hints:['Di chuyển máy thay quan hệ che khuất;tiêu cự thay độ phóng đại.','Bố cục cho phép±22px,tầm cỡ±12px,có nhiều vị trí máy hợp lệ.','Phơi ngắn giảm nhòe,mô hình chuyển động được đơn giản hóa.']};});
creative['print-register']=seq(20).map(i=>{const plateScales=seq(4).map(k=>.8+((i+k*(1+(i/5|0)))%4)*.15),printOrder=seq(4).map(k=>Math.round((k===3?.05+(i%3)*.05:.25+((i+k*2)%9)*.05)*100)/100);return{objective:'In đơn bốn bản CMYK,căn vịtrí/góc/cỡbản riêng và mực cho lệch≤3px,RMSmàu≤9.',singleStage:true,content:{plateScales,printOrder},resources:{plateScales,printOrder,registrationTolerance:3},hints:['Mỗi bản cần đúng cỡ'+plateScales.map(v=>Math.round(v*100)+'%').join('/')+'.','Căn dấu chồng trước khi điều màu;góc nhỏ vẫn gây lệchbiên lớn.','CMYK là mô hình màu trừ đơn giản;không phải mô phỏng profilemáyin thực.']};});
write('creative','creative',creative,['Commission của xưởng nhỏ','Chất liệu có phản hồi','Không gian và bố cục','Bộ sưu tập Bình Minh'],['Theo brief thay vì chép tọa độ','Cân đối vật liệu và chất lượng','Đọc khoảng không,ánh sáng và chồng lớp','Lưu tác phẩm có tiêu chí minh bạch']);
